-- Migration: Seed 123 default teas from teas.ts
-- All teas get source_type='default', source='Teapp', is_public=TRUE, owner_id=NULL

-- First, add new columns to teas table
ALTER TABLE teas ADD COLUMN IF NOT EXISTS source_type TEXT DEFAULT 'default' CHECK (source_type IN ('default', 'user', 'teahouse'));
ALTER TABLE teas ADD COLUMN IF NOT EXISTS source TEXT DEFAULT 'Teapp';
ALTER TABLE teas ADD COLUMN IF NOT EXISTS owner_id UUID REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE teas ADD COLUMN IF NOT EXISTS is_public BOOLEAN DEFAULT TRUE;
ALTER TABLE teas ADD COLUMN IF NOT EXISTS phonetic_name TEXT DEFAULT '';
ALTER TABLE teas ADD COLUMN IF NOT EXISTS original_name TEXT DEFAULT '';
ALTER TABLE teas ADD COLUMN IF NOT EXISTS category TEXT DEFAULT '';
ALTER TABLE teas ADD COLUMN IF NOT EXISTS brewing_num_brews INT DEFAULT 1;
ALTER TABLE teas ADD COLUMN IF NOT EXISTS brewing_instructions TEXT DEFAULT '';
ALTER TABLE teas ADD COLUMN IF NOT EXISTS health_benefits TEXT[] DEFAULT '{}';
ALTER TABLE teas ADD COLUMN IF NOT EXISTS color_hex TEXT DEFAULT '#999';
ALTER TABLE teas ADD COLUMN IF NOT EXISTS oxidation_level INT DEFAULT 50;
ALTER TABLE teas ADD COLUMN IF NOT EXISTS roast_level INT DEFAULT 50;
ALTER TABLE teas ADD COLUMN IF NOT EXISTS flavor_x INT DEFAULT 50;
ALTER TABLE teas ADD COLUMN IF NOT EXISTS flavor_y INT DEFAULT 50;
ALTER TABLE teas ADD COLUMN IF NOT EXISTS wikidata_qid TEXT;
ALTER TABLE teas ADD COLUMN IF NOT EXISTS caffeine_level TEXT DEFAULT 'medium';

UPDATE teas SET source_type = 'default', source = 'Teapp', is_public = TRUE WHERE source_type IS NULL OR source_type = 'default';

-- Insert 123 default teas (ON CONFLICT on slug DO NOTHING if already exists)
-- Using a single transaction
ON CONFLICT (slug) DO UPDATE SET
  phonetic_name = EXCLUDED.phonetic_name,
  original_name = EXCLUDED.original_name,
  description = EXCLUDED.description,
  category = EXCLUDED.category,
  brewing_num_brews = EXCLUDED.brewing_num_brews,
  brewing_instructions = EXCLUDED.brewing_instructions,
  health_benefits = EXCLUDED.health_benefits,
  color_hex = EXCLUDED.color_hex,
  oxidation_level = EXCLUDED.oxidation_level,
  roast_level = EXCLUDED.roast_level,
  flavor_x = EXCLUDED.flavor_x,
  flavor_y = EXCLUDED.flavor_y,
  source_type = 'default',
  source = 'Teapp',
  is_public = TRUE;

-- Migrate existing custom_teas into teas table, then drop custom_teas
SELECT name, slug, description, tea_type, origin, caffeine_level,
  brewing_temp_c::int, brewing_time_min::int, characteristics,
  'user', 'custom', user_id, FALSE
FROM custom_teas
ON CONFLICT (slug) DO NOTHING;

-- Update user_teas: custom tea references now point to teas table
UPDATE user_teas ut
SET tea_id = (SELECT id FROM teas t WHERE t.slug = (SELECT slug FROM custom_teas ct WHERE ct.id = ut.tea_id))
WHERE tea_id NOT IN (SELECT id FROM teas);

-- Update tea_logs: custom tea references now point to teas table
UPDATE tea_logs tl
SET tea_id = (SELECT id FROM teas t WHERE t.slug = (SELECT slug FROM custom_teas ct WHERE ct.id = tl.tea_id))
WHERE tea_id NOT IN (SELECT id FROM teas);

-- Drop custom_teas table
DROP TABLE IF EXISTS custom_teas;

-- Add accent_color to user_preferences
ALTER TABLE user_preferences ADD COLUMN IF NOT EXISTS accent_color TEXT DEFAULT '#c4853f';
